import {
  buildProps,
  definePropType,
  isNumber,
  isString,
} from '@element-plus/utils'
import { inputProps } from '@element-plus/components/input'
import { autocompleteProps } from '@element-plus/components/autocomplete'
import {
  CHANGE_EVENT,
  INPUT_EVENT,
  UPDATE_MODEL_EVENT,
} from '@element-plus/constants'

import type { ExtractPropTypes, __ExtractPublicPropTypes } from 'vue'

export type InputDownValue = string | number
export type InputDownOption = Record<string, unknown>

export const inputDownProps = buildProps({
  ...inputProps,
  modelValue: {
    type: definePropType<InputDownValue>([String, Number]),
    default: '',
  },
  /**
   * @description dropdown options
   */
  options: {
    type: definePropType<InputDownOption[]>(Array),
    default: () => [],
  },
  /**
   * @description key used as the option value and the value filled into the input
   */
  valueKey: {
    type: String,
    default: 'value',
  },
  /**
   * @description key used as the option label
   */
  labelKey: {
    type: String,
    default: 'label',
  },
  placement: autocompleteProps.placement,
  teleported: autocompleteProps.teleported,
  appendTo: autocompleteProps.appendTo,
  popperClass: autocompleteProps.popperClass,
  popperStyle: autocompleteProps.popperStyle,
} as const)

export const inputDownEmits = {
  [UPDATE_MODEL_EVENT]: (value: InputDownValue) =>
    isString(value) || isNumber(value),
  [INPUT_EVENT]: (value: InputDownValue) => isString(value) || isNumber(value),
  [CHANGE_EVENT]: (value: InputDownValue) => isString(value) || isNumber(value),
  select: (option: InputDownOption) => typeof option === 'object',
  focus: (event: FocusEvent) => event instanceof FocusEvent,
  blur: (event: FocusEvent) => event instanceof FocusEvent,
  clear: () => true,
}

export type InputDownProps = ExtractPropTypes<typeof inputDownProps>
export type InputDownPropsPublic = __ExtractPublicPropTypes<
  typeof inputDownProps
>
export type InputDownEmits = typeof inputDownEmits
